import torch
from torch import nn

class RMSNorm(nn.Module):
    """y = x / sqrt(mean(x^2) + eps) * g"""
    def __init__(self, d, eps=1e-6):
        super().__init__()
        self.eps = eps
        self.g = nn.Parameter(torch.ones(d))

    def forward(self, x):
        rms = torch.rsqrt(x.pow(2).mean(dim=-1, keepdim=True) + self.eps)
        return x * rms * self.g


class LayerNormManual(nn.Module):
    """y = (x - mean) / sqrt(var + eps) * g + b"""
    def __init__(self, d, eps=1e-5):
        super().__init__()
        self.eps = eps
        self.g = nn.Parameter(torch.ones(d))
        self.b = nn.Parameter(torch.zeros(d))

    def forward(self, x):
        mu = x.mean(dim=-1, keepdim=True)
        var = x.var(dim=-1, keepdim=True, unbiased=False)
        return (x - mu) / torch.sqrt(var + self.eps) * self.g + self.b

def kv_cache_bytes(B, T, L, H_kv, d_h, bytes_per_elem=2):
    """标准 MHA 的 KV Cache 字节数：B*T*L*H_kv*d_h*2(K和V)*bytes。"""
    return B * T * L * H_kv * d_h * 2 * bytes_per_elem

if __name__ == "__main__":
    n = kv_cache_bytes(1, 10**6, 80, 8, 128, 2)
    print(n, "bytes =", n / 1024**3, "GiB")   # 327680000000 bytes = 305.18 GiB

def binary_search(nums, target):
    """标准二分，返回下标或 -1。"""
    l, r = 0, len(nums) - 1          # 左闭右闭
    while l <= r:
        mid = l + (r - l) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            l = mid + 1
        else:
            r = mid - 1
    return -1


def lower_bound(nums, target):
    """返回第一个 >= target 的下标（可能等于 len）。"""
    l, r = 0, len(nums)              # 左闭右开
    while l < r:
        mid = l + (r - l) // 2
        if nums[mid] < target:
            l = mid + 1
        else:
            r = mid
    return l

def build_next(p: str):
    """next[i] = p[0..i] 的最长相等前后缀长度（不含自身）。"""
    nxt = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j > 0 and p[i] != p[j]:
            j = nxt[j - 1]
        if p[i] == p[j]:
            j += 1
        nxt[i] = j
    return nxt


def kmp_search(s: str, p: str):
    """返回 p 在 s 中所有出现的起始下标，O(n+m)。"""
    if not p:
        return []
    nxt, j, res = build_next(p), 0, []
    for i, ch in enumerate(s):
        while j > 0 and ch != p[j]:
            j = nxt[j - 1]
        if ch == p[j]:
            j += 1
        if j == len(p):
            res.append(i - len(p) + 1)
            j = nxt[j - 1]
    return res

class DSU:
    """路径压缩 + 按秩（大小）合并，近似 O(alpha(n))。"""
    def __init__(self, n):
        self.p = list(range(n))
        self.rank = [0] * n
        self.count = n                      # 连通分量个数

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]    # 路径减半
            x = self.p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True


def num_islands(grid):
    """岛屿数量（lc200）用并查集实现：把每个 '1' 与左/上邻居 union。"""
    if not grid or not grid[0]:
        return 0
    R, C = len(grid), len(grid[0])
    dsu = DSU(R * C)
    ones = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] != "1":
                continue
            ones += 1
            for dr, dc in ((0, -1), (-1, 0)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "1":
                    dsu.union(r * C + c, nr * C + nc)
    # 连通分量数 = 并查集中仍以 '1' 为根的集合数
    roots = {dsu.find(r * C + c) for r in range(R) for c in range(C) if grid[r][c] == "1"}
    return len(roots)

