import torch

def softmax_stable(x, dim=-1):
    """减去 max 防止 exp 上溢；再用 sum 归一化防止下溢导致除零。"""
    x = x - x.max(dim=dim, keepdim=True).values
    e = torch.exp(x)
    return e / (e.sum(dim=dim, keepdim=True) + 1e-12)


def log_softmax_stable(x, dim=-1):
    """log-sum-exp 技巧：log softmax = x - m - log(sum(exp(x - m)))"""
    m = x.max(dim=dim, keepdim=True).values
    z = x - m
    return z - torch.log(torch.exp(z).sum(dim=dim, keepdim=True))

import torch
import torch.nn.functional as F

def cross_entropy_manual(logits, targets, reduction="mean"):
    """logits:[N,C] targets:[N]（类别索引）。CE = -log softmax(logits)[target]"""
    log_probs = F.log_softmax(logits, dim=-1)
    loss = -log_probs.gather(1, targets.unsqueeze(1)).squeeze(1)
    if reduction == "mean":
        return loss.mean()
    if reduction == "sum":
        return loss.sum()
    return loss


def binary_cross_entropy_manual(logits, targets):
    """多标签分类用：每个类别独立 sigmoid；等价于 softmax+CE 在多标签场景不适用。"""
    return F.binary_cross_entropy_with_logits(logits, targets.float())

# 反向传播直觉（面试常被追问）：
# dL/dlogits = softmax(logits) - onehot(target)，再除以 N（mean 时）

import random
from torch.utils.data import Dataset, DataLoader, Sampler

class MyDataset(Dataset):
    def __init__(self, samples, tokenizer, max_len=512):
        self.samples, self.tok, self.max_len = samples, tokenizer, max_len

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        s = self.samples[idx]
        ids = self.tok(s["text"], truncation=True, max_length=self.max_len)["input_ids"]
        return {"input_ids": ids, "label": s["label"]}


def collate_fn(batch, pad_id=0):
    """关键：变长序列要 pad 到本 batch 最长，并生成 attention_mask；labels 侧 padding 置 -100。"""
    maxlen = max(len(b["input_ids"]) for b in batch)
    input_ids, attn, labels = [], [], []
    for b in batch:
        ids = b["input_ids"]
        pad = maxlen - len(ids)
        input_ids.append(ids + [pad_id] * pad)
        attn.append([1] * len(ids) + [0] * pad)
        labels.append(ids + [-100] * pad)
    return {"input_ids": input_ids, "attention_mask": attn, "labels": labels}


class BucketSampler(Sampler):
    """按长度分桶，减少 padding 浪费（面试可讲：等长采样 + 桶内 shuffle）。"""
    def __init__(self, lengths, batch_size, shuffle=True):
        order = sorted(range(len(lengths)), key=lambda i: lengths[i])
        self.batches = [order[i:i + batch_size] for i in range(0, len(order), batch_size)]
        self.shuffle = shuffle

    def __iter__(self):
        bs = self.batches[:]
        if self.shuffle:
            random.shuffle(bs)
        for b in bs:
            yield from b

    def __len__(self):
        return sum(len(b) for b in self.batches)

