    _self_test()
    print('all self-tests passed')

'''100 盏灯与 100 个学生：暴力模拟与「约数奇偶性」推理互相印证。'''


def toggle_simulation(n):
    '''O(n log n) 暴力：第 i 个学生翻转所有 i 的倍数，返回最终亮灯数。'''
    if n < 0:
        raise ValueError('n 必须非负')
    lamps = [False] * (n + 1)          # 下标 0 占位，灯编号 1..n，全关
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):   # j = i, 2i, 3i, ... 即 i 的倍数
            lamps[j] = not lamps[j]    # 切换 = 翻转
    return sum(lamps)


def count_open_by_squares(n):
    '''O(√n) 结论：灯 j 被翻「j 的约数个数」次，只有完全平方数为奇数次。'''
    if n < 0:
        raise ValueError('n 必须非负')
    lo, hi = 0, n + 1                  # 二分求 floor(sqrt(n))，避免浮点误差
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo                          # 亮灯就是 1²,2²,...,lo²


def divisor_count(j):
    '''暴力数 j 的正约数个数，用来验证「翻转次数 = 约数个数」。'''
    return sum(1 for d in range(1, j + 1) if j % d == 0)


if __name__ == '__main__':
    assert toggle_simulation(0) == 0 and count_open_by_squares(0) == 0
    assert toggle_simulation(1) == 1 and count_open_by_squares(1) == 1
    for n in range(1, 401):            # 小规模对拍：模拟结果 == floor(sqrt(n))
        assert toggle_simulation(n) == count_open_by_squares(n), n
    for j in range(1, 61):             # 翻转奇偶性 == 是否完全平方数
        root = count_open_by_squares(j)
        assert (divisor_count(j) % 2 == 1) == (root * root == j), j
    print('100 盏灯最后亮着 %d 盏：1, 4, 9, 16, 25, 36, 49, 64, 81, 100'
          % toggle_simulation(100))

'''1 主 + 3 子多智能体编排的最小可运行模型（纯标准库）。

链路：边界互斥注册 -> 按依赖分波并行 -> 契约校验 -> 带反馈重试 -> 汇总 -> 金标评测。
第 4 个子智能体的取舍：k 个 agent 两两接口是 O(k^2)，新增一个必须先拿出它独占的边界，
否则路由歧义、协调成本上升，吞吐却不变。
'''
import statistics
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field


class BoundaryError(RuntimeError):
    '''任务无人认领，或两个子智能体争抢同一类边界。'''


@dataclass
class Task:
    tid: str
    kind: str
    payload: dict = field(default_factory=dict)
    deps: tuple = ()


class SubAgent:
    kind, name, cost = '', '', 1

    def accepts(self, task):
        return task.kind == self.kind

    def run(self, task):
        raise NotImplementedError


class Retriever(SubAgent):
    kind, name, cost = 'retrieve', '检索子', 3

    def run(self, task):
        rows = [int(v) for v in task.payload.get('rows', [])]
        if not rows:
            raise ValueError('检索子拿到空数据源')
        drift = 1 if task.payload.get('poison') and not task.payload.get('feedback') else 0
        return {'rows': rows, 'n': len(rows) + drift}


class Analyzer(SubAgent):
    kind, name, cost = 'analyze', '分析子', 2

    def run(self, task):
        parts = task.payload.get('inputs') or []
        for p in parts:
            if 'rows' not in p:
                raise ValueError('上游产物缺少 rows 字段')
        rows = [v for p in parts for v in p['rows']]
        if not rows:
            raise ValueError('分析子拿到空数据，拒绝产出')
        return {'mean': round(statistics.fmean(rows), 3),
                'p95': sorted(rows)[min(len(rows) - 1, int(0.95 * len(rows)))],
                'n': len(rows)}


class Writer(SubAgent):
    kind, name, cost = 'write', '写作子', 2

    def run(self, task):
        m = (task.payload.get('inputs') or [{}])[0]
        return {'report': '样本 %s 条，均值 %s，P95 %s' % (m['n'], m['mean'], m['p95'])}


CONTRACT = {'retrieve': {'rows': list, 'n': int},
            'analyze': {'mean': float, 'p95': int, 'n': int},
            'write': {'report': str}}
RULES = {'retrieve': lambda o: [] if o['n'] == len(o['rows']) else ['n 与 rows 长度不一致'],
         'analyze': lambda o: [] if o['n'] > 0 else ['样本数必须为正'],
         'write': lambda o: [] if str(o['report']).strip() else ['报告为空']}


def validate(kind, out):
    if not isinstance(out, dict):
        return ['%s 的输出不是 dict' % kind]
    errs = ['缺少或类型错误的字段 %s' % k for k, t in CONTRACT[kind].items()
            if not isinstance(out.get(k), t)]
    return errs or RULES[kind](out)


class Orchestrator:
    def __init__(self, agents, max_retry=1):
        self.max_retry, self.retries, self.violations = int(max_retry), 0, []
        self.agents, self.by_kind = list(agents), {}
        for a in agents:
            if a.kind in self.by_kind:
                raise BoundaryError('%s 与 %s 的边界重叠：%s' % (a.name, self.by_kind[a.kind], a.kind))
            self.by_kind[a.kind] = a.name

    def route(self, task):
        for a in self.agents:
            if a.accepts(task):
                return a
        raise BoundaryError('任务 %s 的 kind=%s 没有归口' % (task.tid, task.kind))

    def _one(self, task, upstream):
        agent, feedback = self.route(task), None
        for attempt in range(self.max_retry + 1):
            payload = dict(task.payload, inputs=upstream, feedback=feedback)
            try:
                out = agent.run(Task(task.tid, task.kind, payload, task.deps))
                errs = validate(task.kind, out)
            except Exception as exc:
                out, errs = None, ['执行异常：%s' % exc]
            if not errs:
                return out
            feedback = errs
            if attempt < self.max_retry:
                self.retries += 1
                self.violations.append((task.tid, errs))
        raise BoundaryError('%s 重试 %d 次仍不合契约：%s' % (task.tid, self.max_retry, feedback))

    def run_plan(self, tasks):
        pending, done, waves = {t.tid: t for t in tasks}, {}, []
        while pending:
            ready = [t for t in pending.values() if all(d in done for d in t.deps)]
            if not ready:
                raise ValueError('依赖成环或指向不存在的上游')
            waves.append([t.tid for t in ready])
            with ThreadPoolExecutor(max_workers=len(ready)) as pool:
                futs = {t.tid: pool.submit(self._one, t, [done[d] for d in t.deps])
                        for t in ready}
            for t in ready:
                done[t.tid] = futs[t.tid].result()
                pending.pop(t.tid)
        return done, waves


COST = {'retrieve': 3, 'analyze': 2, 'write': 2}


def build_plan(a, b, poison=False):
    return [Task('t1', 'retrieve', {'rows': a, 'poison': poison}),
            Task('t2', 'retrieve', {'rows': b}),
            Task('t3', 'analyze', {}, ('t1', 't2')),
            Task('t4', 'write', {}, ('t3',))]


def makespan(waves, plan):
    kinds = {t.tid: t.kind for t in plan}
    serial = sum(COST[kinds[i]] for w in waves for i in w)
    parallel = sum(max(COST[kinds[i]] for i in w) for w in waves)
    return serial, parallel


GOLD = [('双源合并', [3, 9, 27, 81], [5], False, 5, 25.0, 81),
        ('单条样本', [7], [7], False, 2, 7.0, 7),
        ('脏数据自愈', [1, 2, 3, 4, 5], [7], True, 6, 3.667, 7)]


def evaluate(cases):
    passed, retries = 0, 0
    for name, a, b, poison, n, mean, p95 in cases:
        orc = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=1)
        done, _ = orc.run_plan(build_plan(a, b, poison))
        hit = (done['t3']['n'], done['t3']['mean'], done['t3']['p95']) == (n, mean, p95)
        passed, retries = passed + int(hit), retries + orc.retries
        print('[%s] %s 重试=%d' % ('PASS' if hit else 'FAIL', name, orc.retries))
    return passed, len(cases), retries


if __name__ == '__main__':
    plan = build_plan([3, 9, 27, 81], [5])
    orc = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=1)
    done, waves = orc.run_plan(plan)
    assert waves == [['t1', 't2'], ['t3'], ['t4']], waves
    assert done['t4']['report'] == '样本 5 条，均值 25.0，P95 81', done['t4']
    assert orc.retries == 0 and orc.violations == []
    print('波次:', waves, '串行/并行耗时:', makespan(waves, plan))
    bad = 0
    try:
        Orchestrator([Retriever(), Analyzer(), Analyzer()])
    except BoundaryError:
        bad = 1
    assert bad == 1, '同类边界必须报冲突'
    try:
        orc.route(Task('t9', 'translate'))
    except BoundaryError:
        bad = 2
    assert bad == 2, '无归口任务必须报错'
    hard = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=0)
    try:
        hard.run_plan(build_plan([1, 2, 3, 4, 5], [7], poison=True))
    except BoundaryError:
        bad = 3
    assert bad == 3, '不允许重试时脏数据必须让整条链路失败'
    print('评测:', evaluate(GOLD))
